  VALUES 
    (336::BIGINT, 'es una gran persona, se preocupa por sus estudiantes, pero su método de enseñanza es algo dificil sobre todo si no le gusta leer, en parte también porque el curso es medio obsoleto y aburrido. Los quices son muy duros y lo normal es no pegar las respuesas, los examenes en cambio son un queque'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'f1bf70ac78c7cf599f1ad2fed79f2a03cdf682490df17c0b0d60d0cf17c0e6e7'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'En general es un buen profe, brinda bastante apoyo, las clases se suelen tornar algo aburridas ya que suelen ser un breve resumen de la lectura semanal. En los quices y exámenes es necesario explicar todo por muy obvio que sea, ya que quita bastantes puntos si se de una obviedad por sentado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Brinda apoyo']::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'fadd7d7e734d08f42be240033bb327eebfdd1913dfe43d13b6880d99241f0ff7'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Es un ser humano excepcional y un profesor extraordinario, súper amable, atento y dispuesto ayudar al estudiante para que aprenda. Evaluación: 1 examen teórico 25%, Lecturas 15% y 60% (4 proyectos). Busque gente que quiera trabajar en los proyectos, porque son rudos pero el profe valora el esfuerzo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a5ab5e1c298783938ec612cb2455d6308a4dc4881b6b18678ceef8945e734cb2'::TEXT, ARRAY[1045]::BIGINT[]),
    (336::BIGINT, 'Excelente profesor, crea un ambiente de respeto y confianza entre los estudiantes. A pesar de la dificultad de la materia del curso, lo plantea de una manera en la que los estudiantes aprendan y sea pasable.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, '6fb4f9d14fc7eec10ab0786003cfacc70948d06b712de9662fef6fead130152f'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Excelente profe, es muy sencillo pasar con él. Hay que hacer las lecturas semanales para entender bien las clases. Aclara cualquier duda y es bastante comprensivo con los estudiantes. Prácticamente regala los exámenes pero si usted sigue las varas semanales sí aprende mucho. Súper recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '7c7b38cedcb8b35a008f7721c61ac768aa9571b3167642d8a3ac2d7f6a119589'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Si tiene la oportunidad de matricular no lo dude. Desde la primera clase brinda un calendario con la fecha de entrega de todo lo cual ayuda a organizarse. Siempre que hagan las lecturas semanales y asistan a clase deberían entender, si tienen dudas el profe no duda en explicar nuevamente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fc190d1125b5d9162fb38c40d214cb9b08a4fcf344248333c2d793928d49e77e'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Un excelente profe para análisis, eso si, uno tiene que hacer su parte estudiando lecturas que manda semanalmente para no llegar perdido a la clase. Si uno lee la lectura en la clase uno entiende todo muchísimo mejor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5ddb9bc688d23dbcbe5d833c019b1790782dd5897da252c0e8a72cf14191abe4'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Es un excelente profesor, muy respetuoso y preocupado por la salud mental y el aprendizaje de los estudiantes. Tiene un sistema de evaluaciones con el que es demasiado fácil pasar. Las clases pueden ser un poco largas y aburridas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'cb081e0cbc44d5f01c71a3d6a2e34d31e7b6f1b41426493c3933efb57e12093b'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Es un profesor y persona excelente se preocupa por los alumnos, y tiene un sistema de evaluación muy adecuado, si puede llevar con el hágalo no se va a arrepentir'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'fa3b3dfcda50cabbdefcb5d19b82fd677f3da5d892b15a196a2ed569a20e6c43'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Simplemente no tengo palabras para describir la calidad de profesor que es Diego, tanto como profesor como persona es algo de excelencia, su metodología es sumamente aprovechada por el estudiante. Definitivamente deben de existir más profesores como él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '72e12a939061311057cb3c3955afbb00a120aad4cea1cf764d5fef2d94c0f660'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Es un profe muy tuanis. Las tareas y lecturas que deja cada semana se complementan junto a la clase de una forma que nos deja bastante claro el tema y el enfoque del mismo. Un profe super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, '96e59c7470f088cb1a5e2b665de71620aacde089be121c9addac54bc87ebeb71'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Es un excelente profe, podría decir que el mejor de toda la carrera, explica todo súper y si usted necesita ayuda el se la da, solo para los proyectos es bastante duro para calificar, pero para el resto de asignaciones es un increíble profesor y persona'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, '5f4b28041701c38fda585e71d7bba40c63daee5f4ffc9170f0a9f7d594fd7654'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Llevar este curso con él vale muchísimo la pena, la calidad es excelente. Tiene una organización ejemplar. La claridad en las especificaciones de los trabajos es muy buena. Considera el creditaje del curso, o sea sus trabajos no son excesivamente largos. El proyecto se trabaja en horas de clase c:'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-09T00:00:00+00:00'::TIMESTAMPTZ, '84f859393fb735872c30c7524c982958b094921383ad6795e2a4c51f08b613a4'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Excelente profe se preocupa por que sus estudiantes entiendan, siempre está dispuesto a aclarar dudas por telegram o consulta, no hay examenes, solo un proyecto y varias tareas cortas sencillas y guiadas, Su técnica hace que usted realmente aprenda, lo recomiendo al 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5b950b52702784b2faed50a4469a59664ebed77be3541b20ac360d04834767b1'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Sus progras suelen sonar algo complicadas pero Munguía siempre está ahí para el estudiante, es uno de esos profres que le interesa que ud se lleve una gran experiencia en sus cursos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'fcd3b841f3dc68701e42a259967361f786eac03b6a58a4eaa9fde956c5a888bb'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'De los mejores profesores de programación. Se preocupa por explicar toda la materia. Evaluaciones claras desde el inicio del semestre. Trabajos realizables. Tiene todo muy organizado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '122c4458d352883f3a447a31221c1809a6395acfc18922b6fa472c5bb417c933'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'De los mejores profesores del Tec, es demasiado bueno y se preocupa por darse a entender, eso si, es relativamente fácil aprobar solo que si debe poner de su parte para aprovechar el curso al 100%'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-02T00:00:00+00:00'::TIMESTAMPTZ, '559acf2b5461f1e0b42b2f57fb4c64893041f08aaeecd9b9beb66dbef5c94fa0'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'De los mejores profes que he tenido hasta el momento, súper ordenado, deja tareas semanales que se adaptan muy bien a los temas vistos en clase y no son pesadas, las clases son muy amenas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-03-07T00:00:00+00:00'::TIMESTAMPTZ, '227c776879ef43c8a5433efd3dbcac1c26a667ab99f2704c16c291f594a820a5'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'El profesor mas ordenado que he tenido, sabe mucho del tema, las asignaciones no generan mucha carga, pero son de esas asignaciones donde se logra comprender la materia super bien, si puede matricular con el, va a aprender.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-18T00:00:00+00:00'::TIMESTAMPTZ, 'a6992b2338a0c44bf0cf27048eaea9c5f038bb4e71e44287c8a1aa7dc007a231'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'De los mejores profesores de computación que hay en el TEC, tiene gran conocimiento sobre la materia y es sumamente apasionado. Realiza evaluaciones significativas para enriquecer el proceso de aprendizaje, brinda apoyo y aclara todas las dudas necesarias.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '75bf05606a240e810ead4ff020160d8ac050b64c2d0818ba8640366d5c441d54'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Sinceramente a lo largo de la carrera había perdido un toque la motivación del porque había elegido estudiar computación, pero gracias a este profe logré recordar lo que me trajo aquí y lo entretenido que es el mundo de la programación. Profe si ve esto, gracias :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'd6c8eccd122aa1740026338238e6834f037649bf41b8547c8398cf7357f1fb0a'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Increíble el profe Diego, ayuda al estudiante, sus trabajos son entretenidos, a veces incluso uno termina investigando de más por puro gusto. Las tareas y proyectos son dinámicos y concisos. Además de que el profe enseña tecnología actual, usted ve problemas computacionales del mundo actual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4b439a47e017beaffb11b023154476357aca2aced3f929637a60ec8815cad276'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-09-25T00:00:00+00:00'::TIMESTAMPTZ, '8069f66ac2320274fa29c76b7c46057f57c6dd40db16c3d2b091a52cc4cfc6d9'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Excelente profe, se preocupa por el aprendizaje de los estudiantes y explica muy bien. Se nota que sabe mucho de la materia y aclara dudas. Hay que ponerle para pasar pero es flexible con las entregas, súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'ec3febeeef89a6a3544552e855474634a31195032ab45a37ac6965c612836984'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Excelente profesor, se preocupa de que los estudiantes entiendan. Las clases son largas, pero por lo general son entretenidas. 100% recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas', 'Brinda apoyo']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9da336556bd8ec8dd450915ac399ba428d8f4a9ad1723f9fe7d7b0c51cf9e63c'::TEXT, ARRAY[1035]::BIGINT[]),
    (336::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'd3ead0c543ffd18381763eec8604b9ecd4d7fe83b15b1c74751e4978c82b7e6b'::TEXT, ARRAY[1165]::BIGINT[]),
    (336::BIGINT, 'Un monstruo de profesor, llevar todos los cursos posibles con el'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'dfcc635945c69eeb54560f9d165e776ec3753c5fbdf8887656e1173ae59a41d9'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (336::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-03-14T00:00:00+00:00'::TIMESTAMPTZ, 'd704cc35ff4f4a75b9461ef841a53f106df187218c74a28413f0fded48e38364'::TEXT, ARRAY[1054]::BIGINT[]),
    (336::BIGINT, 'Está entre los 3 mejores profesores que he tenido. No son clases aburridas, más bien dan ganas de quedarse más rato. Conoce muy bien lo que enseña y me gusta que está muy actualizado con las nuevas tecnologías. Más que recomendado.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '0648d007fe7618af3cf8bc9bd6b06ad6b3b6cbd9f9274b8bad8b5298bff20268'::TEXT, ARRAY[1047]::BIGINT[]),
    (336::BIGINT, 'Excelente profesor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '455ce6944f38fc19e7a2a1432d34c0b96c0515d99ef5ea886646f0ce16137a04'::TEXT, ARRAY[1045]::BIGINT[]),
    (336::BIGINT, 'Muy recomendado. Explica bien, sabe bastante y exelente persona.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b71b0780392a2c80ccf9d7a1ae6e1f45d4e087d7141ec9d71c0bd2815f02788f'::TEXT, ARRAY[1030]::BIGINT[]),
    (336::BIGINT, 'Explica excelente,pero se deben tomar apuntes en la clase ya que el objetivo para él es aprender y no dar simplemente la materia. Aclara todo tipo de dudas, incluso dudas fuera ajenas a la materia meta.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '7a7028558b130a588aac27e05a73c977b094886775cb45dcdc69407a6eaab70c'::TEXT, ARRAY[1045, 1047, 1054]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
